html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.4f}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro taken(value) -%}{{ "{:,.2f}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:g}".format((value or 0) | float) }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set p = pay_slip(doc) -%}
<style>
/* Luuka's own slip, to its own measure: a 270pt by 600pt box, Arial 8pt on a
   10pt line, the deductions in a serif on an 11pt line, rules of 5pt dashes
   drawn as lines.
   No table: Frappe's print styles pad every cell (6px, 10px in Redesign) and
   grey every heading, whatever a format says. Every rule here is written
   under .print-format and marked !important where a print style sets the
   same thing on a div or a span. */
.print-format .lpl-slip, .print-format .lpl-slip div, .print-format .lpl-slip span {
  font-family: Arial, Helvetica, sans-serif !important; font-size: 8pt !important; line-height: 10pt !important;
  font-weight: normal; color: #000 !important; box-sizing: border-box; margin: 0; padding: 0; letter-spacing: 0;
  text-align: left; }
.print-format .lpl-slip { position: relative; width: 270pt; min-height: 600pt; border: 1pt solid #000;
  padding: 24.4pt 9pt 20pt 20pt; background: #fff; }
.print-format .lpl-slip .logo { position: absolute; top: 22pt; right: 12pt; width: 66pt; text-align: right; }
.print-format .lpl-slip .logo img { max-width: 66pt; max-height: 34pt; }
.print-format .lpl-slip .r { overflow: hidden; }
.print-format .lpl-slip .b, .print-format .lpl-slip .b div, .print-format .lpl-slip .b span { font-weight: bold; }
.print-format .lpl-slip .in { padding-left: 2pt; }
.print-format .lpl-slip .spaced { letter-spacing: 4.3pt; white-space: nowrap; }

.print-format .lpl-slip .id .r { margin-bottom: 4pt; }
.print-format .lpl-slip .id .r.wide { margin-bottom: 6pt; }
.print-format .lpl-slip .id .k { float: left; width: 75.5pt; padding-left: 2pt; }
.print-format .lpl-slip .id .c { float: left; width: 4.5pt; }
.print-format .lpl-slip .id .val { float: left; width: 155pt; text-transform: uppercase; }
/* the first three lines stand beside the logo */
.print-format .lpl-slip .id .val.by-logo { width: 92pt; }

/* a rule is drawn, not styled: 1pt of 5pt dashes 3pt apart, as theirs, and sharp in a PDF */
.print-format .lpl-slip .rule { display: block; height: 1pt; overflow: hidden; }
.print-format .lpl-slip .rule svg { display: block; }

.print-format .lpl-slip .name { float: left; width: 95pt; }
.print-format .lpl-slip .n { float: left; width: 93pt; text-align: right; white-space: nowrap; }
.print-format .lpl-slip .h { float: left; width: 47pt; text-align: right; white-space: nowrap; }
.print-format .lpl-slip .serif, .print-format .lpl-slip .serif div, .print-format .lpl-slip .serif span {
  font-family: "DejaVu Serif", "Bitstream Vera Serif", "Bookman Old Style", Georgia, serif !important;
  line-height: 11pt !important; }
.print-format .lpl-slip .serif .name { width: 110pt; }
.print-format .lpl-slip .serif .n { width: 85pt; }

.print-format .lpl-slip .days .r { margin-top: 5pt; }
.print-format .lpl-slip .days .k { float: left; width: 73.7pt; padding-left: 2pt; font-weight: bold; }
.print-format .lpl-slip .days .eq { float: right; font-weight: bold; }
.print-format .lpl-slip .days .val { float: left; padding-left: 3.3pt; }
</style>
<div class="lpl-slip">
<div class="logo">{% if logo %}<img src="{{ logo }}">{% endif %}</div>
<div class="id">
<div class="r"><div class="k">NAME</div><div class="c">:</div><div class="val by-logo">{{ v(p.employee_name) }}</div></div>
<div class="r wide"><div class="k">DEPT</div><div class="c">:</div><div class="val by-logo">{{ v(p.department) }}</div></div>
<div class="r wide"><div class="k">PAYROLL NO.</div><div class="c">:</div><div class="val by-logo">{{ v(p.payroll_no) }}</div></div>
<div class="r"><div class="k">PAY SLIP FOR</div><div class="c">:</div><div class="val">{{ v(p.slip_for) }}</div></div>
<div class="r"><div class="k">DESIGNATION</div><div class="c">:</div><div class="val">{{ v(p.designation) }}</div></div>
<div class="r"><div class="k">CATEGORY</div><div class="c">:</div><div class="val">{{ v(p.category) }}</div></div>
<div class="r"><div class="k">SECTION</div><div class="c">:</div><div class="val">{{ v(p.section) }}</div></div>
</div>
<div class="rule" style="margin-left:-1pt;margin-top:0.7pt"><svg width="235pt" height="1pt" viewBox="0 0 235 1"><line x1="0" y1="0.5" x2="235" y2="0.5" stroke="#000" stroke-width="1" stroke-dasharray="5 3"/></svg></div>
<div class="r b" style="margin-top:8.8pt"><div class="name in"><span class="spaced">PAYMENTS</span></div><div class="n">AMOUNT{% if p.currency %} {{ v(p.currency) }}{% endif %}</div><div class="h">HOURS</div></div>
<div class="rule" style="margin-top:2.2pt"><svg width="235pt" height="1pt" viewBox="0 0 235 1"><line x1="0" y1="0.5" x2="235" y2="0.5" stroke="#000" stroke-width="1" stroke-dasharray="5 3"/></svg></div>
<div style="margin-top:1.9pt">
{%- for line in p.payments %}
<div class="r"><div class="name">{{ v(line.name) }}</div><div class="n">{{ money(line.amount) }}</div><div class="h">{% if line.hours %}{{ num(line.hours) }}{% endif %}</div></div>
{%- endfor %}
</div>
<div class="r b" style="margin-top:0.7pt"><div class="name">GROSS PAY</div><div class="n">{{ money(p.gross) }}</div></div>
<div class="rule" style="margin-top:3.2pt"><svg width="188pt" height="1pt" viewBox="0 0 188 1"><line x1="0" y1="0.5" x2="188" y2="0.5" stroke="#000" stroke-width="1" stroke-dasharray="5 3"/></svg></div>
<div class="r b" style="margin-top:2.8pt"><div class="name in">DEDUCTIONS</div><div class="n">AMOUNT{% if p.currency %} {{ v(p.currency) }}{% endif %}</div><div class="h">HOURS</div></div>
<div class="rule" style="margin-top:2.2pt"><svg width="235pt" height="1pt" viewBox="0 0 235 1"><line x1="0" y1="0.5" x2="235" y2="0.5" stroke="#000" stroke-width="1" stroke-dasharray="5 3"/></svg></div>
<div class="serif" style="margin-top:3.9pt">
{%- for line in p.deductions %}
<div class="r"><div class="name">{{ v(line.name) }}</div><div class="n">{{ taken(line.amount) }}</div></div>
{%- endfor %}
</div>
<div class="rule" style="margin-top:0.8pt"><svg width="195pt" height="1pt" viewBox="0 0 195 1"><line x1="0" y1="0.5" x2="195" y2="0.5" stroke="#000" stroke-width="1" stroke-dasharray="5 3"/></svg></div>
<div class="serif b" style="margin-top:1.9pt"><div class="r"><div class="name">TOTAL</div><div class="n">{{ taken(p.total_deductions) }}</div></div></div>
<div class="rule" style="margin-top:1.3pt"><svg width="195pt" height="1pt" viewBox="0 0 195 1"><line x1="0" y1="0.5" x2="195" y2="0.5" stroke="#000" stroke-width="1" stroke-dasharray="5 3"/></svg></div>
<div class="r b" style="margin-top:2.8pt"><div class="name in"><span class="spaced">NETPAY</span></div><div class="n">{{ money(p.net) }}</div></div>
<div class="r b" style="margin-top:5pt"><div class="name">NET PAY R/o</div><div class="n">{{ money(p.rounded) }}</div></div>
<div class="r" style="margin-top:16pt"><span class="b in" style="float:left">PAYMENT BY :</span><span style="float:left;padding-left:4pt">{{ v(p.payment_by) }}</span></div>
<div class="days">
<div class="r"><div class="k"><span class="eq">=</span>Paid Days</div><div class="val">{{ num(p.paid_days) }}</div></div>
<div class="r"><div class="k"><span class="eq">=</span>Working Days</div><div class="val">{{ num(p.working_days) }}</div></div>
<div class="r"><div class="k"><span class="eq">=</span>Holidays</div><div class="val">{{ num(p.holidays) }}</div></div>
<div class="r"><div class="k"><span class="eq">=</span>Absent Amount</div><div class="val">{{ money(p.absent_amount) }}</div></div>
<div class="r"><div class="k"><span class="eq">=</span>Leave Taken</div><div class="val">{{ money(p.leave_taken) }}</div></div>
<div class="r"><div class="k"><span class="eq">=</span>Absent Days</div><div class="val">{{ money(p.absent_days) }}</div></div>
</div>
</div>
